// Block (composition) — a responsive grid of team-member profile cards.
// Grid/Stack own arrangement; Card owns surfaces, Avatar owns identity look, and this Block owns profile content.
import { useState, type Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Media } from "../components/Media";
import { AspectRatio } from "../layouts/AspectRatio";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./TeamGrid.css";

export interface TeamGridProps {
  members: {
    name: string;
    role?: string;
    /** A portrait, shown square and cover-cropped as the card's media. Omitted, or failing to load,
        the card shows the member's initials in an Avatar instead. */
    avatarSrc?: string;
    bio?: string;
  }[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

// A failed load falls back to the initials, as an Avatar does on its own image error.
function Portrait({ name, src }: { name: string; src?: string }) {
  const [failedSrc, setFailedSrc] = useState<string>();
  if (!src || failedSrc === src) {
    return (
      <Avatar size="large" alt={name}>
        {initials(name)}
      </Avatar>
    );
  }
  return (
    <Media className="sd-teamgrid__photo">
      <AspectRatio ratio={1}>
        <img src={src} alt="" onError={() => setFailedSrc(src)} className="sd-teamgrid__image" />
      </AspectRatio>
    </Media>
  );
}

export function TeamGrid({
  members,
  columns = { small: 1, medium: 4 },
  className,
  ref,
}: TeamGridProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Team members"
      columns={columns}
      gap="medium"
      className={className ? `sd-teamgrid ${className}` : "sd-teamgrid"}
    >
      {members.map((member, index) => (
        <Card key={`${member.name}-${index}`}>
          <Stack align="center" gap="small" className="sd-teamgrid__content">
            {/* A photo is the card's media, framed like ProductCard's, because an Avatar tops out at a
                chip's size and a portrait that small reads as an icon beside a large name. Its alt is
                empty: the name is the heading right under it. Without a
                photo the initials Avatar stands in, as before. */}
            <Portrait name={member.name} src={member.avatarSrc} />
            {/* spacing: edge — the portrait paints its own box, a photo or the initials Avatar */}
            {/* A person's name and their role are ONE unit, so they group — at `x-small` because a
                BODY follows them (`token-contract.md` § Choosing a Sys rung, the title↔description
                pair's second case). Flat, the same 4px separated the avatar from the name, the
                name from the role, and the role from the bio: four things at one rung. */}
            <Stack align="center" gap="x-small" className="sd-teamgrid__identity">
              <h3 className="sd-teamgrid__name sd-type-title-medium">{member.name}</h3>
              {member.role && (
                <p className="sd-teamgrid__role sd-type-caption-medium">{member.role}</p>
              )}
            </Stack>
            {member.bio && <p className="sd-teamgrid__bio sd-type-body-medium">{member.bio}</p>}
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

.sd-teamgrid {
  width: 100%;
  text-align: center;
}

.sd-teamgrid__name,
.sd-teamgrid__role,
.sd-teamgrid__bio {
  margin: 0;
}

.sd-teamgrid__bio {
  color: var(--sd-color-text-muted);
}

/* The portrait spans the card's content width and fills its square frame. */
.sd-teamgrid__photo {
  align-self: stretch;
}

.sd-teamgrid__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sd-teamgrid__role {
  color: var(--sd-color-text-muted);
}
